/* ---------- Helpers ---------- */
function colNumToLetters(n){let s="";while(n>0){const r=(n-1)%26;s=String.fromCharCode(65+r)+s;n=Math.floor((n-1)/26);}return s;}
function colLettersToNum(l){let n=0;for(let i=0;i<l.length;i++)n=n*26+(l.charCodeAt(i)-64);return n;}
function parseCell(a1){const m=a1.match(/([A-Z]+)(\d+)/i);return{col:colLettersToNum(m[1].toUpperCase()),row:parseInt(m[2],10)};}
function topLeft(addr){return parseCell(addr.split("!").pop().split(":")[0]);}
function getSheet(ctx,name){return name?ctx.workbook.worksheets.getItem(name):ctx.workbook.worksheets.getActiveWorksheet();}

/* ---------- Ferramentas de LEITURA ---------- */
async function listSheets(){return Excel.run(async(ctx)=>{const s=ctx.workbook.worksheets;s.load("items/name");await ctx.sync();const info=s.items.map((w)=>{const u=w.getUsedRangeOrNullObject(true);u.load(["address","rowCount","columnCount","isNullObject"]);return{name:w.name,used:u};});await ctx.sync();return info.map((r)=>({aba:r.name,areaUsada:r.used.isNullObject?"vazia":r.used.address,linhas:r.used.isNullObject?0:r.used.rowCount,colunas:r.used.isNullObject?0:r.used.columnCount}));});}
async function readRange(sheet,address){return Excel.run(async(ctx)=>{const t=getSheet(ctx,sheet).getRange(address).getUsedRangeOrNullObject(true);t.load(["values","address","rowCount","columnCount","isNullObject"]);await ctx.sync();if(t.isNullObject)return{address,nota:"vazio",values:[]};return{address:t.address,linhas:t.rowCount,colunas:t.columnCount,values:t.values};});}
async function inspectFormulas(sheet,address){return Excel.run(async(ctx)=>{const t=getSheet(ctx,sheet).getRange(address).getUsedRangeOrNullObject(true);t.load(["formulas","address","isNullObject"]);await ctx.sync();if(t.isNullObject)return{address,totalFormulas:0,celulas:[]};const b=topLeft(t.address);const cells=[];const f=t.formulas;for(let r=0;r<f.length;r++)for(let c=0;c<f[r].length;c++){const v=f[r][c];if(typeof v==="string"&&v.startsWith("="))cells.push({celula:colNumToLetters(b.col+c)+(b.row+r),formula:v});}return{address:t.address,totalFormulas:cells.length,celulas:cells};});}
async function getSelection(){return Excel.run(async(ctx)=>{const r=ctx.workbook.getSelectedRange();r.load(["address","values","rowCount","columnCount"]);await ctx.sync();return{address:r.address,linhas:r.rowCount,colunas:r.columnCount,values:r.values};});}
async function findValue(query,sheet){return Excel.run(async(ctx)=>{const u=getSheet(ctx,sheet).getUsedRangeOrNullObject(true);u.load(["values","address","isNullObject"]);await ctx.sync();if(u.isNullObject)return{total:0,matches:[]};const b=topLeft(u.address);const q=String(query).toLowerCase();const m=[];const v=u.values;for(let r=0;r<v.length;r++){for(let c=0;c<v[r].length;c++){const cell=v[r][c];if(cell!==""&&cell!==null&&String(cell).toLowerCase().includes(q)){m.push({celula:colNumToLetters(b.col+c)+(b.row+r),valor:cell});if(m.length>=50)break;}}if(m.length>=50)break;}return{total:m.length,matches:m};});}
async function detectErrors(sheet,address){return Excel.run(async(ctx)=>{const w=getSheet(ctx,sheet);const t=address?w.getRange(address).getUsedRangeOrNullObject(true):w.getUsedRangeOrNullObject(true);t.load(["valueTypes","values","address","isNullObject"]);await ctx.sync();if(t.isNullObject)return{totalErros:0,celulas:[]};const b=topLeft(t.address);const e=[];const ty=t.valueTypes;const v=t.values;for(let r=0;r<ty.length;r++)for(let c=0;c<ty[r].length;c++){if(ty[r][c]===Excel.RangeValueType.error||ty[r][c]==="Error")e.push({celula:colNumToLetters(b.col+c)+(b.row+r),erro:v[r][c]});}return{totalErros:e.length,celulas:e};});}
async function describeRange(sheet,address){return Excel.run(async(ctx)=>{const t=getSheet(ctx,sheet).getRange(address).getUsedRangeOrNullObject(true);t.load(["values","address","isNullObject"]);await ctx.sync();if(t.isNullObject)return{nota:"vazio"};const flat=[];for(const row of t.values)for(const c of row)flat.push(c);const nums=flat.filter((x)=>typeof x==="number");const blanks=flat.filter((x)=>x===""||x===null).length;const uniq=new Set(flat.filter((x)=>x!==""&&x!==null)).size;const o={endereco:t.address,totalCelulas:flat.length,vazias:blanks,unicos:uniq,numericas:nums.length};if(nums.length){let mn=nums[0],mx=nums[0],sum=0;for(const x of nums){if(x<mn)mn=x;if(x>mx)mx=x;sum+=x;}o.soma=sum;o.media=sum/nums.length;o.minimo=mn;o.maximo=mx;}return o;});}
async function getCellDetails(sheet,cell){return Excel.run(async(ctx)=>{const r=getSheet(ctx,sheet).getRange(cell);r.load(["address","values","formulas","numberFormat","valueTypes","text"]);await ctx.sync();return{endereco:r.address,valor:r.values[0][0],textoExibido:r.text[0][0],formula:r.formulas[0][0],formatoNumero:r.numberFormat[0][0],tipo:r.valueTypes[0][0]};});}
async function listTables(){return Excel.run(async(ctx)=>{const t=ctx.workbook.tables;t.load("items/name");await ctx.sync();const info=t.items.map((tb)=>{const rng=tb.getRange();rng.load("address");const h=tb.getHeaderRowRange();h.load("values");return{name:tb.name,rng,h};});await ctx.sync();return info.map((i)=>({nome:i.name,intervalo:i.rng.address,colunas:i.h.values[0]}));});}
async function listNamedRanges(){return Excel.run(async(ctx)=>{const n=ctx.workbook.names;n.load("items/name,items/formula,items/type");await ctx.sync();return n.items.map((x)=>({nome:x.name,refere:x.formula,tipo:x.type}));});}
async function getColumnHeaders(sheet,headerRow){return Excel.run(async(ctx)=>{const u=getSheet(ctx,sheet).getUsedRangeOrNullObject(true);u.load(["values","address","isNullObject"]);await ctx.sync();if(u.isNullObject)return{headers:[]};const b=topLeft(u.address);let idx=headerRow?headerRow-b.row:0;if(idx<0||idx>=u.values.length)idx=0;return{headers:u.values[idx].map((h,i)=>({coluna:colNumToLetters(b.col+i),titulo:h}))};});}
async function getActiveContext(){return Excel.run(async(ctx)=>{const sheet=ctx.workbook.worksheets.getActiveWorksheet();sheet.load("name");const sel=ctx.workbook.getSelectedRange();sel.load("address");const used=sheet.getUsedRangeOrNullObject(true);used.load(["address","values","rowCount","columnCount","isNullObject"]);await ctx.sync();if(used.isNullObject)return{abaAtiva:sheet.name,celulaSelecionada:sel.address,areaUsada:"vazia",valores:[]};const total=used.rowCount*used.columnCount;const valores=total>3000?used.values.slice(0,40):used.values;return{abaAtiva:sheet.name,celulaSelecionada:sel.address,areaUsada:used.address,linhas:used.rowCount,colunas:used.columnCount,valores,truncado:total>3000};});}

/* ---------- Ferramentas de ESCRITA ---------- */
async function writeRange(sheet,startCell,values){return Excel.run(async(ctx)=>{const w=getSheet(ctx,sheet);const rows=values.length,cols=values[0].length;const target=w.getRange(startCell).getResizedRange(rows-1,cols-1);target.values=values;target.load("address");await ctx.sync();return{ok:true,address:target.address};});}
async function writeFormula(sheet,address,formula){return Excel.run(async(ctx)=>{const w=getSheet(ctx,sheet);const range=w.getRange(address);range.load(["rowCount","columnCount","address"]);await ctx.sync();const expr=formula.startsWith("=")?formula:"="+formula;if(range.rowCount===1&&range.columnCount===1){range.formulas=[[expr]];}else{const first=range.getCell(0,0);first.formulas=[[expr]];first.autoFill(range,Excel.AutoFillType.fillDefault);}range.load(["values","valueTypes"]);await ctx.sync();const tipo=range.valueTypes[0][0];const erro=(tipo===Excel.RangeValueType.error||tipo==="Error");return {ok:true,address:range.address,formula:expr,resultado:range.values[0][0],tipo:tipo,erro:erro};});}
async function formatRange(sheet,address,opts){opts=opts||{};return Excel.run(async(ctx)=>{const range=getSheet(ctx,sheet).getRange(address);range.load(["rowCount","columnCount","address"]);await ctx.sync();const f=range.format;if(opts.bold!==undefined)f.font.bold=opts.bold;if(opts.italic!==undefined)f.font.italic=opts.italic;if(opts.fontColor)f.font.color=opts.fontColor;if(opts.fontSize)f.font.size=opts.fontSize;if(opts.fillColor)f.fill.color=opts.fillColor;if(opts.numberFormat){const nf=Array.from({length:range.rowCount},()=>Array(range.columnCount).fill(opts.numberFormat));range.numberFormat=nf;}if(opts.autofitColumns)f.autofitColumns();await ctx.sync();return{ok:true,address:range.address};});}
async function createTable(sheet,address,hasHeaders,name){return Excel.run(async(ctx)=>{const tb=getSheet(ctx,sheet).tables.add(address,hasHeaders!==false);if(name)tb.name=name;tb.load("name");await ctx.sync();return{ok:true,tabela:tb.name};});}
async function createChart(sheet,dataRange,chartType,title){return Excel.run(async(ctx)=>{const w=getSheet(ctx,sheet);const src=w.getRange(dataRange);const type=Excel.ChartType[chartType]||chartType||Excel.ChartType.columnClustered;const ch=w.charts.add(type,src,Excel.ChartSeriesBy.auto);if(title)ch.title.text=title;ch.load("name");await ctx.sync();return{ok:true,grafico:ch.name};});}
async function createSheet(name){return Excel.run(async(ctx)=>{const s=ctx.workbook.worksheets.add(name);s.load("name");await ctx.sync();s.activate();await ctx.sync();return{ok:true,aba:s.name};});}
async function deleteSheet(name){return Excel.run(async(ctx)=>{const sheet=ctx.workbook.worksheets.getItem(name);sheet.delete();await ctx.sync();return{ok:true,aba:name};});}
async function sortRange(sheet,address,columnIndex,ascending,hasHeaders){return Excel.run(async(ctx)=>{const range=getSheet(ctx,sheet).getRange(address);range.sort.apply([{key:columnIndex||0,ascending:ascending!==false}],false,!!hasHeaders);range.load("address");await ctx.sync();return{ok:true,address:range.address};});}
async function findAndReplace(sheet,find,replace,matchCase){return Excel.run(async(ctx)=>{const u=getSheet(ctx,sheet).getUsedRangeOrNullObject(true);u.load("isNullObject");await ctx.sync();if(u.isNullObject)return{substituicoes:0};const res=u.replaceAll(find,replace,{completeMatch:false,matchCase:!!matchCase});await ctx.sync();return{substituicoes:res.value};});}

async function runTool(name,a){try{switch(name){
  case "list_sheets":return await listSheets();
  case "read_range":return await readRange(a.sheet,a.address);
  case "inspect_formulas":return await inspectFormulas(a.sheet,a.address);
  case "get_selection":return await getSelection();
  case "find_value":return await findValue(a.query,a.sheet);
  case "detect_errors":return await detectErrors(a.sheet,a.address);
  case "describe_range":return await describeRange(a.sheet,a.address);
  case "get_cell_details":return await getCellDetails(a.sheet,a.cell);
  case "list_tables":return await listTables();
  case "list_named_ranges":return await listNamedRanges();
  case "get_column_headers":return await getColumnHeaders(a.sheet,a.headerRow);
  case "get_active_context":return await getActiveContext();
  case "write_range":return await writeRange(a.sheet,a.startCell,a.values);
  case "write_formula":return await writeFormula(a.sheet,a.address,a.formula);
  case "format_range":return await formatRange(a.sheet,a.address,a.options);
  case "create_table":return await createTable(a.sheet,a.address,a.hasHeaders,a.name);
  case "create_chart":return await createChart(a.sheet,a.dataRange,a.chartType,a.title);
  case "create_sheet":return await createSheet(a.name);
  case "delete_sheet":return await deleteSheet(a.name);
  case "sort_range":return await sortRange(a.sheet,a.address,a.columnIndex,a.ascending,a.hasHeaders);
  case "find_and_replace":return await findAndReplace(a.sheet,a.find,a.replace,a.matchCase);
  default:return{erro:"Ferramenta desconhecida: "+name};
}}catch(e){return{erro:e.message};}}

/* ---------- Descrição legível e confirmação ---------- */
function describeAction(name,a){const loc=a.sheet?a.sheet+"!":"";switch(name){
  case "write_range":return `Escrever valores a partir de ${loc}${a.startCell}`;
  case "write_formula":return `Escrever a fórmula ${a.formula} em ${loc}${a.address}`;
  case "format_range":return `Formatar ${loc}${a.address}`;
  case "create_table":return `Criar tabela em ${loc}${a.address}`;
  case "create_chart":return `Criar gráfico (${a.chartType||"colunas"}) com dados ${loc}${a.dataRange}`;
  case "create_sheet":return `Criar a aba "${a.name}"`;
  case "delete_sheet":return `EXCLUIR a aba "${a.name}" (não pode ser desfeito)`;
  case "sort_range":return `Ordenar ${loc}${a.address}`;
  case "find_and_replace":return `Substituir "${a.find}" por "${a.replace}"`;
  default:return name;}}

function askConfirmation(text){return new Promise((resolve)=>{
  const card=document.createElement("div");card.className="msg assistant";
  const p=document.createElement("div");p.textContent="Ação proposta: "+text;
  const btns=document.createElement("div");btns.style.cssText="display:flex;gap:6px;margin-top:8px;";
  const yes=document.createElement("button");yes.textContent="Aplicar";yes.style.cssText="background:#217346;color:#fff;border:none;padding:6px 14px;border-radius:4px;cursor:pointer;font-weight:600;";
  const no=document.createElement("button");no.textContent="Cancelar";no.style.cssText="background:#fff;color:#217346;border:1px solid #217346;padding:6px 14px;border-radius:4px;cursor:pointer;font-weight:600;";
  const decide=(ok)=>{pendingConfirm=null;elements.input.disabled=false;yes.disabled=no.disabled=true;p.textContent=(ok?"✓ Aplicado: ":"✗ Cancelado: ")+text;btns.remove();resolve(ok);};pendingConfirm=decide;elements.input.disabled=true;
  yes.onclick=()=>decide(true);no.onclick=()=>decide(false);
  btns.appendChild(yes);btns.appendChild(no);card.appendChild(p);card.appendChild(btns);
  elements.messages.appendChild(card);elements.messages.scrollTop=elements.messages.scrollHeight;
});}

/* ---------- Inicialização e interface ---------- */
Office.onReady((info)=>{if(info.host===Office.HostType.Excel){
  excelLanguage = Office.context.displayLanguage;
  conversation = [{
  role: "system",
  content: SYSTEM_PROMPT + "\n\nIdioma atual do Excel: " + excelLanguage
  }];
  console.log("Display Language:", Office.context.displayLanguage);
  console.log("Content Language:", Office.context.contentLanguage);
  console.log("Host:", info.host);
  elements={messages:document.getElementById("messages"),input:document.getElementById("userInput"),sendBtn:document.getElementById("sendBtn"),newChatBtn:document.getElementById("newChatBtn"),settings:document.getElementById("settings"),settingsBtn:document.getElementById("settingsBtn"),saveSettings:document.getElementById("saveSettings"),apiKey:document.getElementById("apiKey"),model:document.getElementById("model"),historyBtn:document.getElementById("historyBtn"), historyPanel:document.getElementById("historyPanel"), historyList:document.getElementById("historyList"), clearHistoryBtn:document.getElementById("clearHistoryBtn"),};
  loadSettings();
  elements.sendBtn.addEventListener("click",onSend);
  elements.newChatBtn.addEventListener("click",newConversation);
  elements.historyBtn.addEventListener("click",()=>{renderHistory();
  elements.historyPanel.classList.toggle("hidden");
});
  elements.clearHistoryBtn.addEventListener(
  "click",
  clearHistory
);
  elements.settingsBtn.addEventListener("click",()=>elements.settings.classList.toggle("hidden"));
  elements.saveSettings.addEventListener("click",saveSettings);
  elements.input.addEventListener("keydown",(e)=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();onSend();}});
}});
function loadSettings(){elements.apiKey.value=localStorage.getItem("openai_api_key")||"";elements.model.value=localStorage.getItem("openai_model")||"gpt-4.1-mini";if(!elements.apiKey.value)elements.settings.classList.remove("hidden");}
function saveSettings(){localStorage.setItem("openai_api_key",elements.apiKey.value.trim());localStorage.setItem("openai_model",elements.model.value);elements.settings.classList.add("hidden");addMessage("system","Configurações salvas.");}
function saveConversationToHistory(){

  const firstUserMessage =
    conversation.find(m => m.role === "user");

  if(!firstUserMessage) return;

  const history =
    JSON.parse(localStorage.getItem(HISTORY_KEY) || "[]");

  history.unshift({
    id: Date.now(),
    title: firstUserMessage.content.substring(0,60),
    createdAt: new Date().toISOString(),
    messages: conversation
  });

  localStorage.setItem(
    HISTORY_KEY,
    JSON.stringify(history.slice(0,50))
  );
}
function renderHistory(){

  const history =
    JSON.parse(localStorage.getItem(HISTORY_KEY) || "[]");

  elements.historyList.innerHTML = "";

  history.forEach(item => {

    const div = document.createElement("div");

    div.className = "history-item";

    div.innerHTML = `
      <div class="history-title">${item.title}</div>
      <div class="history-date">
        ${new Date(item.createdAt).toLocaleString()}
      </div>
    `;

    div.onclick = () => {

      conversation = item.messages;
      prevResponseId = null;

      elements.messages.innerHTML = "";

      item.messages.forEach(m => {

        if(
          m.role === "system" ||
          m.role === "tool"
        ) return;

        addMessage(
          m.role === "assistant"
            ? "assistant"
            : "user",
          m.content || ""
        );
      });

    elements.historyPanel.classList.add("hidden");
    
    showToast("✓ Histórico apagado");
    };

    elements.historyList.appendChild(div);
  });
}
function clearHistory(){

  localStorage.removeItem(HISTORY_KEY);

  renderHistory();

  elements.historyPanel.classList.add("hidden");
}
function newConversation(){

  saveConversationToHistory();
  prevResponseId = null;

  conversation = [{
    role: "system",
    content: SYSTEM_PROMPT + "\n\nIdioma atual do Excel: " + excelLanguage
  }];

  elements.messages.innerHTML = `
    <div class="msg system">
      Como posso ajudar com sua planilha hoje?
    </div>
  `;
}
function addMessage(role,text){const d=document.createElement("div");d.className="msg "+role;d.textContent=text;elements.messages.appendChild(d);elements.messages.scrollTop=elements.messages.scrollHeight;return d;}
function setBusy(b){elements.sendBtn.disabled = b;elements.sendBtn.textContent = b ? "..." : "Enviar";}
let pendingConfirm=null;
function onSend(){if(elements.sendBtn.disabled||pendingConfirm)return;const t=elements.input.value.trim();if(!t)return;elements.input.value="";addMessage("user",t);conversation.push({role:"user",content:t});askOpenAI(t);}

/* ---------- Conversa com a IA ---------- */
async function askOpenAI(userText){
  const key=localStorage.getItem("openai_api_key");
  const model=localStorage.getItem("openai_model")||"gpt-4.1-mini";
  if(!key){addMessage("error","Configure sua chave da API no botão ⚙.");elements.settings.classList.remove("hidden");return;}
  setBusy(true);
  const placeholder=addMessage("assistant","Pensando...");
  const t0=Date.now();let statusText="⏳ Processando...";
  const timer=setInterval(()=>{placeholder.textContent=statusText+" ("+Math.floor((Date.now()-t0)/1000)+"s)";},1000);
  let input=[{role:"user",content:userText}];
  try{
    for(let i=0;i<12;i++){
      elements.messages.appendChild(placeholder);placeholder.className="msg assistant";statusText="⏳ Processando...";elements.messages.scrollTop=elements.messages.scrollHeight;
      const body={model:model,instructions:SYSTEM_PROMPT+"\n\nIdioma atual do Excel: "+excelLanguage,input:input,tools:tools,tool_choice:"auto"};
      if(prevResponseId)body.previous_response_id=prevResponseId;
      const resp=await fetch("https://api.openai.com/v1/responses",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+key},body:JSON.stringify(body)});
      if(!resp.ok){const t=await resp.text();placeholder.className="msg error";placeholder.textContent="Erro da API ("+resp.status+"): "+t;return;}
      const data=await resp.json();
      prevResponseId=data.id;
      const calls=(data.output||[]).filter((o)=>o.type==="function_call");
      if(calls.length){
        const outputs=[];
        for(const call of calls){
          const name=call.name;let args={};try{args=JSON.parse(call.arguments||"{}");}catch(e){}
          if(WRITE_TOOLS.has(name)){statusText="Aguardando sua confirmação...";placeholder.textContent=statusText;const ok=await askConfirmation(describeAction(name,args));if(!ok){outputs.push({type:"function_call_output",call_id:call.call_id,output:JSON.stringify({recusado:true,mensagem:"O usuário não autorizou esta ação."})});continue;}}
          else{statusText="Trabalhando...";}
          const result=await runTool(name,args);
          let out=JSON.stringify(result);if(out.length>12000)out=out.slice(0,12000)+"...[truncado]";
          outputs.push({type:"function_call_output",call_id:call.call_id,output:out});
        }
        input=outputs;
        continue;
      }
      let answer="";for(const o of (data.output||[])){if(o.type==="message"&&o.content){for(const c of o.content){if(c.type==="output_text"&&c.text)answer+=c.text;}}}
      answer=answer.trim()||"(sem resposta)";
      placeholder.textContent=answer;
      conversation.push({role:"assistant",content:answer});
      return;
    }
    placeholder.textContent="(muitas etapas seguidas — tente reformular)";
  }catch(e){placeholder.className="msg error";placeholder.textContent="Falha: "+e.message;}
  finally{clearInterval(timer);setBusy(false);}
}
     
function showToast(message){

  const toast = document.createElement("div");

  toast.className = "toast";

  toast.textContent = message;

  document.body.appendChild(toast);

  setTimeout(()=>{
    toast.classList.add("show");
  },10);

  setTimeout(()=>{
    toast.remove();
  },2500);
}